```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // PG* env vars
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');

function decodeCursor(raw) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(raw, 'base64url').toString());
    return typeof ts === 'string' && typeof id === 'string' ? [ts, id] : null;
  } catch {
    return null;
  }
}

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || DEFAULT_LIMIT, 1), MAX_LIMIT);

  const params = [limit + 1]; // one extra row tells us whether there is a next page
  let where = '';
  if (req.query.cursor !== undefined) {
    const cursor = decodeCursor(String(req.query.cursor));
    if (!cursor) return res.status(400).json({ error: 'invalid cursor' });
    params.push(...cursor);
    where = 'WHERE (created_at, id) < ($2::timestamptz, $3::bigint)';
  }

  try {
    const { rows } = await pool.query(
      `SELECT o.*,
              to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS cursor_ts
         FROM orders o
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params
    );

    const page = rows.slice(0, limit);
    const next_cursor = rows.length > limit ? encodeCursor(page[page.length - 1]) : null;
    res.json({ data: page.map(({ cursor_ts, ...order }) => order), next_cursor });
  } catch (err) {
    // class 22 = data exception: a well-formed cursor carrying a bad timestamp or id
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;
```

