- **Cursor timestamp:** it comes from `to_char`, not the JS `Date`. `Date` truncates Postgres microseconds to milliseconds, which makes rows get skipped or repeated at page boundaries.
- **Assumptions:** `created_at` is `timestamptz` and `NOT NULL`, and `id` is `bigint` (which `pg` returns as a string). For an integer or UUID `id`, change the `$3` cast and the `typeof id` check.
- **Not included:** this route returns every customer's orders. Before exposing it, add authentication and a `customer_id = $n` filter, and put `customer_id` first in the index.

```ts
type Job<T> = () => Promise<T>;

export class JobQueue {
  private pending: Array<() => Promise<void>> = [];
  private running = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(private concurrency: number, private maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
  }

  /** Enqueue a job. Resolves with its result, or rejects with the last error once retries run out. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        // chisle: retries immediately; add backoff if jobs hit rate-limited services
        for (let attempt = 0; ; attempt++) {
          try {
            resolve(await job());
            return;
          } catch (err) {
            if (attempt >= this.maxRetries) {
              reject(err);
              return;
            }
          }
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.running++;
      run().finally(() => {
        this.running--;
        this.next();
      });
    }
    if (this.running === 0 && this.pending.length === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}
```

Check (ES module, for the top-level `await`):

```ts
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const q = new JobQueue(2);
let active = 0, peak = 0, calls = 0;

for (let i = 0; i < 6; i++) {
  q.add(async () => { peak = Math.max(peak, ++active); await sleep(10); active--; });
}
const flaky = q.add(async () => { if (++calls < 3) throw new Error("fail"); return "ok"; });
const dead = q.add(async () => { throw new Error("always"); }).catch((e) => e.message);

await q.onIdle();
console.assert(peak === 2 && calls === 3 && (await flaky) === "ok" && (await dead) === "always");
```

- **Retry count:** three retries means up to four attempts per job. A retrying job keeps its concurrency slot.
- **Failures:** `onIdle()` resolves even if jobs failed; failures surface only through the promise `add()` returns. Handle or `.catch` that promise, because an ignored rejection is an unhandled rejection, which terminates Node by default.
